const menuBtn=document.getElementById("menu-btn"),menu=document.getElementById("menu"),closeBtn=document.getElementById("close-btn");menuBtn.addEventListener("click",(()=>{menu.style.display="block"})),closeBtn.addEventListener("click",(()=>{menu.style.display="none"})),document.addEventListener("click",(e=>{menu.contains(e.target)||e.target===menuBtn||(menu.style.display="none")}));